import{_ as a,o as e,c as i,a5 as n}from"./chunks/framework.a5no_H3L.js";const o=JSON.parse('{"title":"游戏开发与 Unity 的定位","description":"你会任意一门编程语言，但还没做过游戏。读完这一篇，你能说清游戏开发和普通应用开发的本质区别，理解 Unity 用「场景 + 组件 + 脚本」这套模型解决了什么问题，并知道它和 Godot、Unreal 的取舍。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"unity/01-getting-started/chapter-01-why-unity.md","filePath":"unity/01-getting-started/chapter-01-why-unity.md"}'),r={name:"unity/01-getting-started/chapter-01-why-unity.md"};function d(s,t,c,l,y,h){return e(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="游戏开发与-unity-的定位" tabindex="-1" data-src-line="2" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">游戏开发与 Unity 的定位 <a class="header-anchor" href="#游戏开发与-unity-的定位" aria-label="Permalink to &quot;游戏开发与 Unity 的定位&quot;">​</a></h1><p data-src-line="4" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">你会任意一门编程语言，但还没做过游戏。读完这一篇，你能说清游戏开发和普通应用开发的本质区别，理解 Unity 用「场景 + 组件 + 脚本」这套模型解决了什么问题，并知道它和 Godot、Unreal 的取舍。</p><h2 id="_1-游戏开发与普通应用的区别" tabindex="-1" data-src-line="6" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">1. 游戏开发与普通应用的区别 <a class="header-anchor" href="#_1-游戏开发与普通应用的区别" aria-label="Permalink to &quot;1. 游戏开发与普通应用的区别&quot;">​</a></h2><p data-src-line="8" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">普通应用（网页、后台服务、命令行工具）大多是<strong>事件驱动</strong>的：程序启动后等待输入，收到请求就处理、返回结果，然后继续等待。两个请求之间程序可以完全空闲。</p><p data-src-line="10" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">游戏是<strong>帧驱动</strong>的：无论玩家是否操作，画面都要以固定频率持续刷新。游戏世界里的物体每帧都在移动、碰撞、播放动画、响应物理，即使玩家什么都不做，这些状态也在持续演进。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通应用：启动 → 等待事件 → 处理 → 返回 → 继续等待</span></span>
<span class="line"><span>游戏：     启动 → 每帧循环（读取输入 → 更新状态 → 渲染画面）→ 直到退出</span></span></code></pre></div><p data-src-line="17" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">这个区别带来三个直接后果：</p><ul data-src-line="19" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><li data-src-line="19" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><strong>实时性</strong>：玩家按下跳跃键，角色必须在几十毫秒内做出反应，否则会感到&quot;卡&quot;。延迟的要求比大多数后台服务严格得多。</li><li data-src-line="20" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><strong>每帧都要算</strong>：渲染、物理、动画、寻路都需要在每帧（约 16.7ms，对应 60 帧/秒）内完成。任何一帧超时都会表现为掉帧。</li><li data-src-line="21" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><strong>状态高度耦合</strong>：一个角色的位置同时被输入、物理、动画、镜头等多个系统读写，比单次请求处理的状态管理复杂得多。</li></ul><h2 id="_2-unity-是什么" tabindex="-1" data-src-line="23" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">2. Unity 是什么 <a class="header-anchor" href="#_2-unity-是什么" aria-label="Permalink to &quot;2. Unity 是什么&quot;">​</a></h2><p data-src-line="25" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">Unity 是 Unity Technologies 开发的游戏引擎，由三部分组成：</p><ul data-src-line="27" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><li data-src-line="27" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><strong>引擎运行时</strong>：负责渲染、物理、动画、音频、输入、资源加载等底层能力。</li><li data-src-line="28" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><strong>编辑器</strong>：一个可视化工具，用来搭建场景、摆放物体、调参数、看运行结果。</li><li data-src-line="29" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><strong>脚本层</strong>：用 C# 写游戏逻辑，通过 Unity 提供的 API 驱动引擎。</li></ul><p data-src-line="31" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">三者的关系可以这样理解：引擎运行时提供能力，编辑器让你可视化地组装场景，脚本把&quot;玩家按了跳跃键&quot;这样的输入翻译成对引擎能力的调用。</p><h2 id="_3-unity-用「场景-组件-脚本」解决什么问题" tabindex="-1" data-src-line="33" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">3. Unity 用「场景 + 组件 + 脚本」解决什么问题 <a class="header-anchor" href="#_3-unity-用「场景-组件-脚本」解决什么问题" aria-label="Permalink to &quot;3. Unity 用「场景 + 组件 + 脚本」解决什么问题&quot;">​</a></h2><p data-src-line="35" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">Unity 的核心模型只有三个概念，但贯穿所有工作：</p><h3 id="_3-1-场景-scene" tabindex="-1" data-src-line="37" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">3.1 场景（Scene） <a class="header-anchor" href="#_3-1-场景-scene" aria-label="Permalink to &quot;3.1 场景（Scene）&quot;">​</a></h3><p data-src-line="39" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">场景是游戏世界的容器，可以理解成一个&quot;关卡&quot;或&quot;一个界面&quot;。一个 3D 场景里放着灯光、地形、角色、摄像机等物体。游戏运行时会加载某个场景，玩家看到和操作的就是这个场景里的内容。</p><h3 id="_3-2-游戏对象与组件-gameobject-与-component" tabindex="-1" data-src-line="41" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">3.2 游戏对象与组件（GameObject 与 Component） <a class="header-anchor" href="#_3-2-游戏对象与组件-gameobject-与-component" aria-label="Permalink to &quot;3.2 游戏对象与组件（GameObject 与 Component）&quot;">​</a></h3><p data-src-line="43" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">Unity 里几乎一切可见、可交互的东西都是 <strong>GameObject</strong>（游戏对象）。但 GameObject 本身只是一个空容器，它没有任何行为。</p><p data-src-line="45" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">行为由挂在它身上的<strong>组件（Component）</strong> 赋予。例如：</p><ul data-src-line="47" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><li data-src-line="47" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">一个 GameObject 加上 <code>Transform</code> 组件，就有了位置、旋转和缩放；</li><li data-src-line="48" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">加上 <code>Mesh Renderer</code> 组件，才能被渲染出来；</li><li data-src-line="49" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">加上 <code>Rigidbody</code> 组件，才参与物理模拟；</li><li data-src-line="50" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">加上你自己写的脚本组件，才有自定义逻辑。</li></ul><p data-src-line="52" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">这就是 Unity 的<strong>组件化</strong>思想：不通过继承一个庞大的&quot;游戏物体&quot;基类来获得能力，而是把能力拆成一个个小组件，按需组合。这比深继承层次更灵活，也更容易复用。</p><h3 id="_3-3-脚本-script" tabindex="-1" data-src-line="54" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">3.3 脚本（Script） <a class="header-anchor" href="#_3-3-脚本-script" aria-label="Permalink to &quot;3.3 脚本（Script）&quot;">​</a></h3><p data-src-line="56" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">脚本是用 C# 写的组件。它继承 <code>MonoBehaviour</code>，Unity 在特定时机自动调用脚本里定义好的方法（如每帧调用 <code>Update</code>）。你写脚本就是在告诉 Unity：&quot;每帧把这个物体向前移动一段距离&quot;或&quot;玩家碰到这个物体时扣血&quot;。</p><p data-src-line="58" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">C# 语言本身不在这里展开，需要时看 <a href="./../../csharp/">C# 专题</a>。</p><h2 id="_4-为什么选-unity-三选一" tabindex="-1" data-src-line="60" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">4. 为什么选 Unity：三选一 <a class="header-anchor" href="#_4-为什么选-unity-三选一" aria-label="Permalink to &quot;4. 为什么选 Unity：三选一&quot;">​</a></h2><p data-src-line="62" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">新手常问 Unity、Godot、Unreal 怎么选。它们不是&quot;好坏&quot;之分，而是取舍不同：</p><table tabindex="0"><thead data-src-line="64" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><tr data-src-line="64" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><th>引擎</th><th>语言</th><th>强项</th><th>弱项</th></tr></thead><tbody data-src-line="66" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><tr data-src-line="66" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><td>Unity</td><td>C#</td><td>生态最大、教程最多、跨平台最广（主机/PC/移动/Web）、2D 和 3D 都成熟</td><td>源码闭源、部分高级功能需付费订阅</td></tr><tr data-src-line="67" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><td>Unreal</td><td>C++ / 蓝图</td><td>画面天花板高、大厂 3A 常用</td><td>上手门槛高、2D 和移动端偏弱</td></tr><tr data-src-line="68" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><td>Godot</td><td>GDScript / C#</td><td>完全开源免费、轻量</td><td>生态和教程相对少、主机支持弱</td></tr></tbody></table><p data-src-line="70" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">对&quot;会编程但没做过游戏&quot;的读者，Unity 的优势在于：C# 是工程友好的静态类型语言，官方和社区教程数量最多，遇到问题最容易找到答案。Unreal 适合追求极致画面的团队，Godot 适合偏好开源和轻量的个人开发者。</p><h2 id="_5-一个最小工作流" tabindex="-1" data-src-line="72" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">5. 一个最小工作流 <a class="header-anchor" href="#_5-一个最小工作流" aria-label="Permalink to &quot;5. 一个最小工作流&quot;">​</a></h2><p data-src-line="74" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">把前三节串起来，Unity 里做一个小功能通常是这几步：</p><ol data-src-line="76" data-src-file="unity/01-getting-started/chapter-01-why-unity.md"><li data-src-line="76" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">在场景里放一个 GameObject（比如一个立方体）。</li><li data-src-line="77" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">给它挂组件：默认有 <code>Transform</code>，再加 <code>Mesh Renderer</code> 和 <code>Box Collider</code>。</li><li data-src-line="78" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">写一个 C# 脚本组件，在 <code>Update</code> 里让物体每帧旋转。</li><li data-src-line="79" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">把脚本挂到这个 GameObject 上，点播放，看到它转起来。</li></ol><p data-src-line="81" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">后面四篇会一步步带你完成这个过程：先装好环境（<a href="./chapter-02-installation.html">安装 Unity Hub 与选择 LTS 版本</a>），再认识编辑器（<a href="./chapter-03-editor-workspace.html">编辑器界面与工作区</a>），最后做出第一个会动的项目（<a href="./chapter-04-first-project.html">第一个项目：场景、GameObject 与组件</a>）。</p><h2 id="_6-版本说明" tabindex="-1" data-src-line="83" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">6. 版本说明 <a class="header-anchor" href="#_6-版本说明" aria-label="Permalink to &quot;6. 版本说明&quot;">​</a></h2><p data-src-line="85" data-src-file="unity/01-getting-started/chapter-01-why-unity.md">本专题以 <strong>Unity 6.3 LTS（版本号 6000.3）</strong> 为验证基准，该版本于 2025 年 12 月发布，支持至 2027 年 12 月。Unity 6 起采用新的发布节奏：每年一个 LTS 版本，其间穿插只支持到下一版本发布为止的 Update release。新项目建议选 LTS，理由在下一篇详细说明。</p>`,34)])])}const g=a(r,[["render",d]]);export{o as __pageData,g as default};
